export function getTrainerTierByChallenge(challengeNum: number): number {
  if (challengeNum <= 1) return 1;
  if (challengeNum <= 3) return 2;
  if (challengeNum <= 5) return 3;
  return 4;
}

export function selectFactoryTrainerTemplate(params: {
  challengeNum: number;
  isBoss: boolean;
  isSpecialUnlockBoss: boolean;
  usedTrainerIds?: Set<string>;
}): FactoryTrainerTemplate {
  const { challengeNum, isBoss, isSpecialUnlockBoss, usedTrainerIds = new Set<string>() } = params;
  const targetTier = Math.min(4, getTrainerTierByChallenge(challengeNum) + (isBoss ? 1 : 0) + (isSpecialUnlockBoss ? 1 : 0));
  const challengeCandidates = FACTORY_TRAINER_TEMPLATES.filter((template) => challengeNum >= template.challengeTierMin && challengeNum <= template.challengeTierMax);
  const pool = challengeCandidates.length > 0 ? challengeCandidates : FACTORY_TRAINER_TEMPLATES;
  const fresh = pool.filter((template) => !usedTrainerIds.has(template.id));
  const candidatePool = fresh.length > 0 ? fresh : pool;
  let best = candidatePool[0] ?? FACTORY_TRAINER_TEMPLATES[0];
  let bestScore = -Infinity;
  for (const template of candidatePool) {
    const distancePenalty = Math.abs(template.tierHint - targetTier) * 6;
    const bossBonus = isBoss ? template.betterRangeSlots * 1.5 : 0;
    const unlockBossBonus = isSpecialUnlockBoss ? template.qualityBiasOffset * 2 : 0;
    const score = (20 - distancePenalty) + bossBonus + unlockBossBonus + Math.random();
    if (score > bestScore) {
      bestScore = score;
      best = template;
    }
  }
  return best;
}
